import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Twitch.html","title":"Twitch","lang":"en-US","frontmatter":{},"git":{"createdTime":1715835934000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":6}]},"readingTime":{"minutes":0.27,"words":82},"filePathRelative":"Twitch.md"}`),a={name:`Twitch.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="twitch" tabindex="-1"><a class="header-anchor" href="#twitch"><span>Twitch</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a></p><p><a href="./YouTubeAPI.html">YouTubeAPI</a>があまりにもドキュメントやサンプルにやる気が無いので、Twitchを調べてみる。</p><p>Twitch、ゲーム実況などで割と使われている印象で、以前シェアハウスで良く見ている人が居て隣で見てた事があるが、 自分ではあまり見た事が無いので良く知らない。</p><p><a href="https://dev.twitch.tv/gamedevelopers/" target="_blank" rel="noopener noreferrer">Twitch Game Developer Playbook - Twitch Developers</a> ゲーム開発者向けの情報が充実してそうな雰囲気だな。読んでみよう。 読んでみた。マーケティング用パワポという感じで開発者が求めているhow toとかでは無かった。</p><h3 id="配信周り" tabindex="-1"><a class="header-anchor" href="#配信周り"><span>配信周り</span></a></h3><ul><li><a href="https://dev.twitch.tv/docs/video-broadcast/" target="_blank" rel="noopener noreferrer">Video Broadcast - Twitch Developers</a><ul><li><a href="https://help.twitch.tv/s/article/broadcasting-guidelines?language=en_US" target="_blank" rel="noopener noreferrer">Broadcasting Guidelines</a></li></ul></li></ul><p>iOS側は<a href="./Mac.html">Mac</a>にまとめるか。</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};